class Solution { private boolean assign(int index,int[] quantity,int[] capacity){if(index<0)return true;int previous=-1;for(int i=0;i<capacity.length;i++)if(capacity[i]>=quantity[index]&&capacity[i]!=previous){int before=capacity[i];capacity[i]-=quantity[index];if(assign(index-1,quantity,capacity))return true;capacity[i]=before;previous=before;}return false;}public boolean canDistribute(int[] nums,int[] quantity){Map<Integer,Integer> counts=new HashMap<>();for(int value:nums)counts.put(value,counts.getOrDefault(value,0)+1);int[] capacity=counts.values().stream().mapToInt(Integer::intValue).toArray();Arrays.sort(quantity);return assign(quantity.length-1,quantity,capacity);} }
